package dev.yequi.emotes;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.EmoteClue;

/**
 * Reads the active emote clue from the core clue scroll plugin.
 */
@Singleton
class ClueScrollEmotes
{
	private final PluginManager pluginManager;
	private ClueScrollPlugin cluePlugin;

	@Inject
	private ClueScrollEmotes(PluginManager pluginManager)
	{
		this.pluginManager = pluginManager;
	}

	boolean isHighlighting()
	{
		ClueScrollPlugin plugin = findCluePlugin();
		if (plugin == null || !pluginManager.isPluginActive(plugin))
		{
			return false;
		}
		ClueScroll clue = plugin.getClue();
		return clue instanceof EmoteClue && ((EmoteClue) clue).getFirstEmote().hasSprite();
	}

	@Nullable
	private ClueScrollPlugin findCluePlugin()
	{
		if (cluePlugin == null)
		{
			for (Plugin plugin : pluginManager.getPlugins())
			{
				if (plugin instanceof ClueScrollPlugin)
				{
					cluePlugin = (ClueScrollPlugin) plugin;
					break;
				}
			}
		}
		return cluePlugin;
	}
}

