import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.components.TextComponent;

public class EmoteOverlay extends Overlay
{
	private static final Map<String, String> SHORT_NAMES = ImmutableMap.of("Hypermobile Drinker", "H. Drinker");

	private final EmotesPlugin plugin;
	private final EmotesConfig config;
	private final Client client;
	private final ClueScrollEmotes clueScrollEmotes;
	private final TextComponent textComponent = new TextComponent();
	private final Map<String, LabelLayout> labelLayouts = new HashMap<>();
	private List<Font> labelFonts;

	@Inject
	private EmoteOverlay(EmotesPlugin plugin, EmotesConfig config, Client client, ClueScrollEmotes clueScrollEmotes)
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		this.plugin = plugin;
		this.config = config;
		this.client = client;
		this.clueScrollEmotes = clueScrollEmotes;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget emoteContainer = client.getWidget(InterfaceID.Emote.CONTENTS);
		if (emoteContainer == null || emoteContainer.isHidden())
		{
			return null;
		}
		Widget emoteWindow = client.getWidget(InterfaceID.Emote.UNIVERSE);
		if (emoteWindow == null)
		{
			return null;
		}
		updateLabelFonts(graphics.getFont());
		Map<Integer, EmoteHighlight> highlights = plugin.getHighlights();
		Map<Integer, String> labels = plugin.getLabels();
		int[] spriteIds = config.emoteToScrollTo().getSpriteIds();
		// the clue scroll plugin's highlights take priority over all labels
		boolean showLabels = config.displayLabels() && !clueScrollEmotes.isHighlighting();
		for (Widget emoteWidget : emoteContainer.getDynamicChildren())
		{
			// scroll to the specified item
			for (int spriteId : spriteIds)
			{
				if (spriteId == emoteWidget.getSpriteId())
				{
					plugin.scrollToHighlight(emoteWidget);
					break;
				}
			}
			Emote emote = EmotesPlugin.emoteFromWidget(emoteWidget);
			if (emote != null)
			{
				String label = showLabels ? getLabel(emoteWidget, labels.get(emote.ordinal())) : null;
				renderEmote(graphics, emoteWidget, emoteWindow, highlights.get(emote.ordinal()), label);
			}
		}
		return null;
	}

	private void renderEmote(Graphics2D graphics, Widget emoteWidget, Widget container,
							 @Nullable EmoteHighlight highlight, @Nullable String label)
	{
		Point canvasLocation = emoteWidget.getCanvasLocation();
		if (canvasLocation == null)
		{
			return;
		}

		Point windowLocation = container.getCanvasLocation();
		if (windowLocation.getY() > canvasLocation.getY() + emoteWidget.getHeight()
			|| windowLocation.getY() + container.getHeight() < canvasLocation.getY())
		{
			return;
		}

		if (highlight != null)
		{
			renderHighlight(graphics, highlight, emoteWidget, canvasLocation, container, windowLocation);
		}

		if (!Strings.isNullOrEmpty(label))
		{
			renderLabel(graphics, label, emoteWidget, canvasLocation, container, windowLocation, highlight);
		}
	}

	private void renderLabel(Graphics2D graphics, String text, Widget emoteWidget, Point canvasLocation,
							 Widget container, Point windowLocation, @Nullable EmoteHighlight highlight)
	{
		// keep a 2px gap on each side so labels on neighboring emotes don't touch
		LabelLayout layout = labelLayouts.computeIfAbsent(text,
			t -> LabelLayout.fit(graphics, t, emoteWidget.getWidth() - 4, labelFonts));
		FontMetrics fontMetrics = graphics.getFontMetrics(layout.getFont());
		List<String> lines = layout.getLines();

		// the last line sits on the bottom edge of the emote, and earlier lines stack above it
		int bottom = canvasLocation.getY() + emoteWidget.getHeight();
		int top = bottom - fontMetrics.getAscent() - (lines.size() - 1) * fontMetrics.getHeight();
		if (top < windowLocation.getY() || bottom > windowLocation.getY() + container.getHeight())
		{
			return;
		}

		textComponent.setFont(layout.getFont());
		textComponent.setColor(highlight != null && config.rememberEmoteColors()
			? highlight.getTextColor() : config.labelColor());
		for (int i = 0; i < lines.size(); i++)
		{
			String line = lines.get(i);
			textComponent.setPosition(new java.awt.Point(
				canvasLocation.getX() + emoteWidget.getWidth() / 2 - fontMetrics.stringWidth(line) / 2,
				bottom - (lines.size() - 1 - i) * fontMetrics.getHeight()));
			textComponent.setText(line);
			textComponent.render(graphics);
		}
	}

	private void renderHighlight(Graphics2D graphics, EmoteHighlight highlight, Widget emoteWidget,
								 Point canvasLocation, Widget container, Point windowLocation)
	{
		// Visible area of widget
		Area widgetArea = new Area(
			new Rectangle(
				canvasLocation.getX(),
				Math.max(canvasLocation.getY(), windowLocation.getY()),
				emoteWidget.getWidth(),
				Math.min(
					Math.min(windowLocation.getY() + container.getHeight() - canvasLocation.getY(), emoteWidget.getHeight()),
					Math.min(canvasLocation.getY() + emoteWidget.getHeight() - windowLocation.getY(), emoteWidget.getHeight()))
			));

		Color fillColor = config.rememberEmoteColors() ? highlight.getFillColor() : config.fillColor();
		Color borderColor = config.rememberEmoteColors() ? highlight.getBorderColor() : config.borderColor();
		Color borderHoverColor = borderColor.darker();
		OverlayUtil.renderHoverableArea(graphics, widgetArea, client.getMouseCanvasPosition(), fillColor, borderColor,
			borderHoverColor);
	}

	@Nullable
	private String getLabel(Widget emoteWidget, @Nullable String customLabel)
	{
		if (!Strings.isNullOrEmpty(customLabel))
		{
			return customLabel;
		}
		if (!config.autoLabel())
		{
			return null;
		}
		String name = EmotesPlugin.emoteNameFromWidget(emoteWidget);
		return SHORT_NAMES.getOrDefault(name, name);
	}

	/**
	 * Sets the fonts that labels can use, smallest last, and clears cached layouts if the overlay font changed.
	 */
	private void updateLabelFonts(Font overlayFont)
	{
		if (labelFonts != null && labelFonts.get(0).equals(overlayFont))
		{
			return;
		}
		labelFonts = ImmutableList.of(overlayFont, FontManager.getRunescapeSmallFont());
		labelLayouts.clear();
	}
}

