	String KEY_LABELS = "savedLabels";
	String KEY_LEFT_CLICKS = "savedLeftClicks";

	@Alpha
	@ConfigItem(
		position = 1,
		keyName = "borderColor",
		name = "Border color",
		description = "Color of border around the emote"
	)
	default Color borderColor()
	{
		return Color.ORANGE;
	}

	@Alpha
	@ConfigItem(
		position = 2,
		keyName = "fillColor",
		name = "Fill color",
		description = "Color of fill highlight on emote"
	)
	default Color fillColor()
	{
		return new Color(0, 255, 0, 20);
	}

	@ConfigItem(
		position = 3,
		keyName = "labelColor",
		name = "Label color",
		description = "Color of label on emote"
	)
	default Color labelColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		position = 4,
		keyName = "rememberEmoteColors",
		name = "Remember color per emote",
		description = "Uses the colors from time of placement on each emote"
	)
	default boolean rememberEmoteColors()
	{
		return false;
	}

