		position = 5,
		keyName = "displayLabels",
		name = "Display labels",
		description = "Shows/hides labels for all emotes"
	)
	default boolean displayLabels()
	{
		return true;
	}

	@ConfigItem(
		position = 6,
		keyName = "autoLabel",
		name = "Auto-label",
		description = "Labels every emote without a custom label"
	)
