	@ConfigItem(
		position = 7,
		keyName = "emoteToScrollTo",
		name = "Emote to scroll to",
		description = "Scrolls to this emote whenever the tab resets (if scroll mode enabled)"
	)
	default Emote emoteToScrollTo()
	{
		return Emote.YES;
	}

	@ConfigItem(
		position = 8,
		keyName = "scrollMode",
		name = "Scroll mode",
		description = "Where the scrolled-to emote will appear relative to the container"
	)
	default ScrollMode scrollMode()
	{
		return ScrollMode.DISABLED;
	}

	@ConfigItem(
		position = 8,
		keyName = "scrollMode",
		name = "Scroll mode",
		description = "Where the scrolled-to emote will appear relative to the container",
		hidden = true
	)
	void setScrollMode(ScrollMode mode);

	@ConfigItem(
		keyName = KEY_HIGHLIGHTS,
		name = "Highlighted emote info",
		description = "Map of sprite ids to highlight",
		hidden = true
	)
	default String savedHighlightInfoV2()
	{
		return "";
	}

	@ConfigItem(
		keyName = KEY_HIGHLIGHTS,
		name = "Highlighted emote info",
		description = "Map of sprite ids to highlight",
		hidden = true
	)
	void setSavedHighlightInfoV2(String serializedInfo);

	@ConfigItem(
		keyName = KEY_LABELS,
		name = "Emote labels",
		description = "Map of emote ids to custom labels",
		hidden = true
	)
	default String savedLabels()
	{
		return "";
	}

	@ConfigItem(
		keyName = KEY_LABELS,
		name = "Emote labels",
		description = "Map of emote ids to custom labels",
		hidden = true
	)
	void setSavedLabels(String serializedLabels);

	@ConfigItem(
		keyName = KEY_LEFT_CLICKS,
		name = "Emote left-click options",
		description = "Map of emote ids to left-click options",
		hidden = true
	)
