package dev.yequi.emotes;

import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Value;

/**
 * Font and lines for a label wrapped onto at most two lines.
 */
@Value
class LabelLayout
{
	Font font;
	List<String> lines;

	/**
	 * Returns the layout in the first font that fits, within maxWidth.
	 */
	static LabelLayout fit(Graphics2D graphics, String text, int maxWidth, List<Font> fonts)
	{
		LabelLayout layout = null;
		for (Font font : fonts)
		{
			FontMetrics fontMetrics = graphics.getFontMetrics(font);
			List<String> lines = wrap(text, fontMetrics, maxWidth);
			layout = new LabelLayout(font, lines);
			if (widest(lines, fontMetrics) <= maxWidth)
			{
				break;
			}
		}
		return layout;
	}

	/**
	 * Returns the text as one line if it fits. Otherwise, splits the text onto
	 * two lines, keeping the wider of the two as small as possible.
	 */
	private static List<String> wrap(String text, FontMetrics fontMetrics, int maxWidth)
	{
		List<String> best = Collections.singletonList(text);
		int bestWidth = fontMetrics.stringWidth(text);
		if (bestWidth <= maxWidth)
		{
			return best;
		}
		String[] words = text.trim().split("\\s+");
		for (int i = 1; i < words.length; i++)
		{
			List<String> lines = Arrays.asList(
				String.join(" ", Arrays.copyOfRange(words, 0, i)),
				String.join(" ", Arrays.copyOfRange(words, i, words.length)));
			int width = widest(lines, fontMetrics);
			if (width < bestWidth)
			{
				best = lines;
				bestWidth = width;
			}
		}
		return best;
	}

	private static int widest(List<String> lines, FontMetrics fontMetrics)
	{
		return lines.stream().mapToInt(fontMetrics::stringWidth).max().orElse(0);
	}
}

package dev.yequi.emotes;

import com.google.common.base.Strings;
import com.google.common.reflect.TypeToken;
import com.google.gson.Gson;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * Saves and applies a left-click option for each emote.
 */
@Singleton
class LeftClickSwapper
{
	private final EmotesConfig config;
	private final Gson gson;
	private Map<Integer, String> swaps = new HashMap<>();

	@Inject
	private LeftClickSwapper(EmotesConfig config, Gson gson)
	{
		this.config = config;
		this.gson = gson;
	}

	void load()
	{
		String json = config.savedLeftClicks();
		if (Strings.isNullOrEmpty(json))
		{
			swaps = new HashMap<>();
			return;
		}
		//@formatter:off
		Type type = new TypeToken<Map<Integer, String>>(){}.getType();
		//@formatter:on
		swaps = gson.fromJson(json, type);
	}

	/**
	 * Adds a "Swap left-click" submenu that lists the emote's options.
	 */
	void addMenuEntry(Menu menu, Widget emoteWidget, int emoteId)
	{
		if (emoteWidget.getActions() == null)
		{
			return;
		}
		Menu subMenu = menu.createMenuEntry(1)
			.setOption("Swap left-click")
			.setTarget("")
			.setType(MenuAction.RUNELITE)
			.createSubMenu();
		for (String action : emoteWidget.getActions())
		{
			if (Strings.isNullOrEmpty(action))
			{
				continue;
			}
			String option = Text.removeTags(action);
			subMenu.createMenuEntry(0)
				.setOption(option)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> save(emoteId, option));
		}
		if (swaps.containsKey(emoteId))
		{
			subMenu.createMenuEntry(0)
				.setOption("Reset")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> save(emoteId, null));
		}
	}

	/**
	 * Moves the saved option to left-click if the top menu entry is for an emote.
	 */
	void swap(Menu menu)
	{
		if (swaps.isEmpty())
		{
			return;
		}
		MenuEntry[] entries = menu.getMenuEntries();
		int top = entries.length - 1;
		if (top < 0 || !isEmoteEntry(entries[top]) || entries[top].getWidget() == null)
		{
			return;
		}
		Emote emote = EmotesPlugin.emoteFromWidget(entries[top].getWidget());
		String option = emote == null ? null : swaps.get(emote.ordinal());
		if (option == null || isOption(entries[top], option))
		{
			return;
		}
		for (int i = top - 1; i >= 0; i--)
		{
			MenuEntry entry = entries[i];
			if (isEmoteEntry(entry) && entry.getParam0() == entries[top].getParam0() && isOption(entry, option))
			{
				// low priority entries are right-click only
				if (entry.getType() == MenuAction.CC_OP_LOW_PRIORITY)
				{
					entry.setType(MenuAction.CC_OP);
				}
				entries[i] = entries[top];
				entries[top] = entry;
				menu.setMenuEntries(entries);
				return;
			}
		}
	}

	private void save(int emoteId, String option)
	{
		if (option == null)
		{
			swaps.remove(emoteId);
		}
		else
		{
			swaps.put(emoteId, option);
		}
		config.setSavedLeftClicks(gson.toJson(swaps));
	}

	private static boolean isEmoteEntry(MenuEntry entry)
	{
		return entry.getParam1() == InterfaceID.Emote.CONTENTS;
	}

	private static boolean isOption(MenuEntry entry, String option)
	{
		return Text.removeTags(entry.getOption()).equals(option);
	}
}

